package star.tracto.preprocessing;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;
import static star.tracto.preprocessing.TokensFixture.candidatesAfter;

/**
 * End-to-end test of the body in the contextual information of a method without a source (Step 35): the accessor of a
 * record (generated by the compiler) and a method of the JDK read by reflection ({@code Enum.compareTo}). Their body was
 * taken from the text of the object describing the method ({@code {declaration=...ImplicitGetterMethod@1ab268bd, ...}},
 * with an identity hash for the records, changing from one run to another); they have no body.
 */
class SourcelessBodyTokensTest {

    @TempDir
    Path tempDir;

    private TokensFixture fixture;

    @BeforeEach
    void setUp() throws IOException {
        fixture = new TokensFixture(tempDir);
        fixture.write("src/main/java/com/acme/Entry.java", """
                package com.acme;

                public record Entry(String name) {
                }
                """);
        fixture.write("src/main/java/com/acme/Level.java", """
                package com.acme;

                public enum Level {
                    LOW, HIGH
                }
                """);
        fixture.write("src/test/java/com/acme/EntryTest.java", """
                package com.acme;

                import org.junit.jupiter.api.Test;
                import static org.junit.jupiter.api.Assertions.*;

                public class EntryTest {
                    @Test
                    public void testName() {
                        Entry entry = new Entry("a");
                        assertEquals("a", entry.name());
                    }

                    @Test
                    public void testLevel() {
                        assertTrue(Level.LOW.compareTo(Level.HIGH) < 0);
                    }
                }
                """);
    }

    @Test
    void aMethodWithoutASourceHasNoBody() throws IOException {
        fixture.generate();

        assertEquals(Map.of(), fixture.unexpectedTokens());
        Map<String, JsonNode> datapoints = fixture.tokensDatapoints();
        // The methods are offered (their contextual information is built)
        assertTrue(candidatesAfter(datapoints.get("testName_split_0"), "assertEquals(\"a\",entry.").contains("name"));
        assertTrue(candidatesAfter(datapoints.get("testLevel_split_0"), "assertTrue(Level.LOW.").contains("compareTo"));
        List<String> bodies = new ArrayList<>();
        for (JsonNode datapoint : datapoints.values()) {
            collectBodies(datapoint, bodies);
        }
        assertFalse(bodies.isEmpty());
        assertEquals(List.of(), bodies.stream().filter(body -> body.contains("declaration=")).distinct().toList());
    }

    /** The values of the fields {@code body} anywhere in a JSON tree. */
    private static void collectBodies(JsonNode node, List<String> bodies) {
        if (node.isObject()) {
            node.fields().forEachRemaining(field -> {
                if (field.getKey().equals("body") && field.getValue().isTextual()) {
                    bodies.add(field.getValue().asText());
                } else {
                    collectBodies(field.getValue(), bodies);
                }
            });
        } else if (node.isArray()) {
            node.forEach(child -> collectBodies(child, bodies));
        }
    }
}
